import { TrackBox } from "@opendaw/studio-boxes";
import { asInstanceOf, isDefined, UUID } from "@opendaw/lib-std";
import { UnionBoxTypes } from "@opendaw/studio-adapters";
export var RecordTrack;
(function (RecordTrack) {
    const TAKE_LABEL = /^Take (\d{1,9})$/;
    RecordTrack.findOrCreate = (editing, audioUnitBox, type, excludeTrack = null) => {
        let index = 0 | 0;
        const trackBoxes = audioUnitBox.tracks.pointerHub.incoming()
            .map(({ box }) => asInstanceOf(box, TrackBox))
            .sort((a, b) => a.index.getValue() - b.index.getValue());
        for (const trackBox of trackBoxes) {
            if (trackBox !== excludeTrack) {
                const hasNoRegions = trackBox.regions.pointerHub.isEmpty();
                const matchesType = trackBox.type.getValue() === type;
                if (hasNoRegions && matchesType) {
                    return trackBox;
                }
            }
            index = Math.max(index, trackBox.index.getValue());
        }
        return editing.modify(() => createAt(audioUnitBox, type, index + 1)).unwrap("Could not create TrackBox");
    };
    RecordTrack.nextIndex = (audioUnitBox) => audioUnitBox.tracks.pointerHub.incoming()
        .reduce((index, { box }) => Math.max(index, asInstanceOf(box, TrackBox).index.getValue() + 1), 0);
    // a new track below every other track of the unit
    RecordTrack.createBelow = (audioUnitBox, type) => createAt(audioUnitBox, type, RecordTrack.nextIndex(audioUnitBox));
    const createAt = (audioUnitBox, type, index) => TrackBox.create(audioUnitBox.graph, UUID.generate(), box => {
        box.type.setValue(type);
        box.index.setValue(index);
        box.tracks.refer(audioUnitBox.tracks);
        box.target.refer(audioUnitBox);
    });
    RecordTrack.lastTakeNumber = (audioUnitBox) => {
        let highest = 0;
        for (const { box: trackBox } of audioUnitBox.tracks.pointerHub.incoming()) {
            for (const { box } of asInstanceOf(trackBox, TrackBox).regions.pointerHub.incoming()) {
                const match = TAKE_LABEL.exec(UnionBoxTypes.asRegionBox(box).label.getValue());
                if (isDefined(match)) {
                    highest = Math.max(highest, parseInt(match[1]));
                }
            }
        }
        return highest;
    };
})(RecordTrack || (RecordTrack = {}));
