import { Notifier, Option, tryCatch } from "@opendaw/lib-std";
// measured round trips per output and input device, kept in this browser like the device names they are keyed by
export var BrowserRoundTrips;
(function (BrowserRoundTrips) {
    const Key = "opendaw:round-trips";
    const notifier = new Notifier();
    const isEntry = (value) => {
        if (typeof value !== "object" || value === null) {
            return false;
        }
        const { output, input, sampleRate, seconds, measuredAt } = value;
        return typeof output === "string" && typeof input === "string" && typeof sampleRate === "number"
            && typeof seconds === "number" && Number.isFinite(seconds) && typeof measuredAt === "number";
    };
    BrowserRoundTrips.all = () => {
        const { status, value } = tryCatch(() => JSON.parse(localStorage.getItem(Key) ?? "[]"));
        return status === "success" && Array.isArray(value) ? value.filter(isEntry) : [];
    };
    BrowserRoundTrips.find = (output, input, sampleRate) => Option.wrap(BrowserRoundTrips.all().find(entry => entry.output === output && entry.input === input && entry.sampleRate === sampleRate));
    const store = (entries) => {
        tryCatch(() => localStorage.setItem(Key, JSON.stringify(entries)));
        notifier.notify();
    };
    const others = (output, input, sampleRate) => BrowserRoundTrips.all().filter(entry => !(entry.output === output && entry.input === input && entry.sampleRate === sampleRate));
    BrowserRoundTrips.save = (entry) => store([...others(entry.output, entry.input, entry.sampleRate), entry]);
    BrowserRoundTrips.remove = (output, input, sampleRate) => {
        if (BrowserRoundTrips.find(output, input, sampleRate).isEmpty()) {
            return;
        }
        store(others(output, input, sampleRate));
    };
    BrowserRoundTrips.subscribe = (observer) => notifier.subscribe(observer);
})(BrowserRoundTrips || (BrowserRoundTrips = {}));
