import { Arrays, DefaultObservableValue, isDefined, isNull, MutableObservableOption, Notifier, Option, RuntimeNotifier, SetMultimap, SyncStream, Terminator, UUID } from "@opendaw/lib-std";
import { RenderQuantum } from "@opendaw/lib-dsp";
import { Communicator, Messenger } from "@opendaw/lib-runtime";
import { DeviceBoxUtils, EngineSettingsSchema, EngineStateSchema, ExportConfiguration, PERF_BUFFER_SIZE, PreferencesHost } from "@opendaw/studio-adapters";
import { AnimationFrame } from "@opendaw/lib-dom";
import { EngineVariant } from "./EngineVariant";
import { MonitoringRouter } from "./MonitoringRouter";
import { MIDIReceiver } from "./midi";
import { HRClockWorker } from "./HRClockWorker";
import { WclapBundles, WclapFailures, WclapGuis, WclapParameters, WclapStates } from "./wclap";
export class EngineWorklet extends AudioWorkletNode {
    static ID = 0 | 0;
    id = EngineWorklet.ID++;
    #terminator = new Terminator();
    #project;
    #playbackTimestamp = new DefaultObservableValue(0.0);
    #position = new DefaultObservableValue(0.0);
    #bpm = new DefaultObservableValue(120.0);
    #isPlaying = new DefaultObservableValue(false);
    #isRecording = new DefaultObservableValue(false);
    #isCountingIn = new DefaultObservableValue(false);
    #countInBeatsRemaining = new DefaultObservableValue(0);
    #compensationLatency = new DefaultObservableValue(0);
    #compensationExceeded = new DefaultObservableValue(false);
    #preferences;
    #markerState = new DefaultObservableValue(null);
    #cpuLoad = new DefaultObservableValue(0);
    #recordingStart = new MutableObservableOption();
    #recordingStop = Option.None;
    #recordingGeneration = 0;
    #controlFlags;
    #notifyClipNotification;
    #notifyNoteSignals;
    #notifyTransportAnchors;
    #playingClips;
    #deviceMessageListeners = new SetMultimap();
    #wclapStatusListeners = new SetMultimap();
    #wclapStatus = new Map();
    #commands;
    #frozenAudioWriter;
    #isReady;
    #perfBuffer = new Float32Array(0);
    #perfIndex = 0;
    #lastPerfReadIndex = 0;
    #consecutiveOverloadCount = 0;
    #lastCpuLoadUpdate = 0;
    #maxMsSinceLastUpdate = 0;
    #monitoringRouter = null;
    constructor(context, project, exportConfiguration, options) {
        const numberOfChannels = ExportConfiguration.countStems(Option.wrap(exportConfiguration)) * 2;
        const budgetMs = (RenderQuantum / context.sampleRate) * 1000;
        const reader = SyncStream.reader(EngineStateSchema(), state => {
            this.#isPlaying.setValue(state.isPlaying);
            const { recordingStopTime } = state;
            if (this.#recordingStop.mapOr(stop => stop.contextTime !== recordingStopTime, true)) {
                this.#recordingStop = Number.isFinite(recordingStopTime)
                    ? Option.wrap({ contextTime: recordingStopTime }) : Option.None;
            }
            this.#isRecording.setValue(state.isRecording);
            this.#isCountingIn.setValue(state.isCountingIn);
            this.#countInBeatsRemaining.setValue(state.countInBeatsRemaining);
            this.#compensationLatency.setValue(state.compensationLatency);
            this.#compensationExceeded.setValue(state.compensationExceeded);
            this.#playbackTimestamp.setValue(state.playbackTimestamp);
            this.#bpm.setValue(state.bpm);
            this.#perfBuffer = state.perfBuffer;
            this.#perfIndex = state.perfIndex;
            this.#updateCpuLoad(budgetMs, project);
            this.#position.setValue(state.position); // This must be the last to handle the state values before
        });
        const controlFlagsSAB = new SharedArrayBuffer(4); // 4 bytes minimum
        // The engine is ALWAYS the installed variant (the wasm engine). There is no built-in fallback
        // processor to drop to, so an absent provider is a boot error rather than a silent downgrade.
        const variant = EngineVariant.current();
        super(context, variant.processorName, {
            numberOfInputs: 1,
            numberOfOutputs: 2,
            outputChannelCount: [numberOfChannels, 8],
            processorOptions: {
                syncStreamBuffer: reader.buffer,
                controlFlagsBuffer: controlFlagsSAB,
                hrClockBuffer: HRClockWorker.get().sab,
                project: project.toArrayBuffer(),
                exportConfiguration,
                options,
                variant: variant.attachment
            }
        });
        const { resolve, promise: isReady } = Promise.withResolvers();
        const messenger = Messenger.for(this.port);
        this.#project = project;
        this.#isReady = isReady;
        this.#notifyClipNotification = this.#terminator.own(new Notifier());
        this.#notifyNoteSignals = this.#terminator.own(new Notifier());
        this.#notifyTransportAnchors = this.#terminator.own(new Notifier());
        this.#playingClips = [];
        this.#controlFlags = new Int32Array(controlFlagsSAB);
        this.#commands = this.#terminator.own(Communicator.sender(messenger.channel("engine-commands"), dispatcher => new class {
            play() { dispatcher.dispatchAndForget(this.play); }
            stop(reset) { dispatcher.dispatchAndForget(this.stop, reset); }
            setPosition(position) { dispatcher.dispatchAndForget(this.setPosition, position); }
            prepareRecordingState(countIn, generation) {
                dispatcher.dispatchAndForget(this.prepareRecordingState, countIn, generation);
            }
            stopRecording() { dispatcher.dispatchAndForget(this.stopRecording); }
            queryLoadingComplete() {
                return dispatcher.dispatchAndReturn(this.queryLoadingComplete);
            }
            panic() { dispatcher.dispatchAndForget(this.panic); }
            sleep() { dispatcher.dispatchAndForget(this.sleep); }
            wake() { dispatcher.dispatchAndForget(this.wake); }
            loadClickSound(index, data) {
                dispatcher.dispatchAndForget(this.loadClickSound, index, data);
            }
            setFrozenAudio(uuid, audioData) {
                dispatcher.dispatchAndForget(this.setFrozenAudio, uuid, audioData);
            }
            noteSignal(signal) { dispatcher.dispatchAndForget(this.noteSignal, signal); }
            ignoreNoteRegion(uuid) {
                dispatcher.dispatchAndForget(this.ignoreNoteRegion, uuid);
            }
            suspendAutomation(uuid) {
                dispatcher.dispatchAndForget(this.suspendAutomation, uuid);
            }
            scheduleClipPlay(clipIds) {
                dispatcher.dispatchAndForget(this.scheduleClipPlay, clipIds);
            }
            scheduleClipStop(trackIds) {
                dispatcher.dispatchAndForget(this.scheduleClipStop, trackIds);
            }
            setupMIDI(port, buffer) {
                dispatcher.dispatchAndForget(this.setupMIDI, port, buffer);
            }
            updateMonitoringMap(map) {
                dispatcher.dispatchAndForget(this.updateMonitoringMap, map);
            }
            wclapOpenGui(uuid) { return dispatcher.dispatchAndReturn(this.wclapOpenGui, uuid); }
            wclapCloseGui(uuid) { dispatcher.dispatchAndForget(this.wclapCloseGui, uuid); }
            wclapOpenPanel(uuid, height) {
                return dispatcher.dispatchAndReturn(this.wclapOpenPanel, uuid, height);
            }
            wclapResizeGui(uuid, width, height) {
                return dispatcher.dispatchAndReturn(this.wclapResizeGui, uuid, width, height);
            }
            wclapReceive(uuid, bytes) {
                dispatcher.dispatchAndForget(this.wclapReceive, uuid, bytes);
            }
            wclapSaveState(uuid) { dispatcher.dispatchAndForget(this.wclapSaveState, uuid); }
            wclapDescribe(url) {
                return dispatcher.dispatchAndReturn(this.wclapDescribe, url);
            }
            wclapRetry(url) { dispatcher.dispatchAndForget(this.wclapRetry, url); }
            scriptMessage(uuid, message) { dispatcher.dispatchAndForget(this.scriptMessage, uuid, message); }
            overrideDeviceField(uuid, key, value) {
                dispatcher.dispatchAndForget(this.overrideDeviceField, uuid, key, value);
            }
            querySignalGraph() { return dispatcher.dispatchAndReturn(this.querySignalGraph); }
            terminate() { dispatcher.dispatchAndForget(this.terminate); }
        }));
        this.#frozenAudioWriter = isDefined(variant.connectFrozenAudio)
            ? variant.connectFrozenAudio(messenger) : null;
        this.#monitoringRouter = this.#terminator.own(new MonitoringRouter(this, this.#commands));
        const { port, sab } = this.#terminator.own(MIDIReceiver.create(MIDIReceiver.outputClock(context, () => this.#compensationLatency.getValue() * 1000), (deviceId, data, timestamp) => this.#project.sendMIDIFromEngine(deviceId, data, timestamp)));
        this.#commands.setupMIDI(port, sab);
        Communicator.executor(messenger.channel("engine-to-client"), {
            log: (message) => console.log("WORKLET", message),
            error: (reason) => this.dispatchEvent(new ErrorEvent("error", { error: reason })),
            notice: (notice) => RuntimeNotifier.notify({ message: this.#describeNotice(notice) }),
            deviceMessage: (uuid, message) => {
                for (const listener of this.#deviceMessageListeners.get(uuid)) {
                    listener(message);
                }
            },
            ready: () => resolve(),
            fetchAudio: (uuid) => {
                const record = (event) => variant.recordSampleLoad?.(event);
                record({ type: "requested", uuid });
                return new Promise((resolve, reject) => {
                    const handler = project.sampleManager.getOrCreate(uuid);
                    const subscription = handler.subscribe(state => {
                        if (state.type === "error") {
                            record({ type: "failed", uuid });
                            reject(new Error(state.reason));
                            subscription.terminate();
                        }
                        else if (state.type === "loaded") {
                            const data = handler.data.unwrap("handler.data");
                            const { numberOfFrames, numberOfChannels, sampleRate } = data;
                            record({ type: "delivered", uuid, numberOfFrames, numberOfChannels, sampleRate });
                            resolve(data);
                            subscription.terminate();
                        }
                    });
                });
            },
            fetchSoundfont: (uuid) => {
                return new Promise((resolve, reject) => {
                    const handler = project.soundfontManager.getOrCreate(uuid);
                    const subscription = handler.subscribe(state => {
                        if (state.type === "error") {
                            reject(new Error(state.reason));
                            subscription.terminate();
                        }
                        else if (state.type === "loaded") {
                            resolve(handler.soundfont.unwrap("handler.soundfont"));
                            subscription.terminate();
                        }
                    });
                });
            },
            fetchNamWasm: async () => {
                const url = new URL("@opendaw/nam-wasm/nam.wasm", import.meta.url);
                const response = await fetch(url);
                return response.arrayBuffer();
            },
            fetchWclapBundle: (url) => WclapBundles.fetch(url),
            wclapSend: (uuid, bytes) => WclapGuis.deliver(uuid, bytes),
            wclapState: (uuid, bytes, url, clapId, cause) => WclapStates.storeFrom(project, uuid, bytes, url, clapId, cause),
            wclapParams: (uuid, params) => WclapParameters.reconcile(project, uuid, params),
            wclapParam: (uuid, paramId, value, gesture) => WclapParameters.apply(project, uuid, paramId, value, gesture),
            wclapHovered: (uuid, paramId) => WclapGuis.hover(uuid, paramId),
            wclapResizeGui: (uuid, width, height) => WclapGuis.resize(uuid, width, height),
            wclapShowGui: (uuid) => WclapGuis.show(uuid, true),
            wclapHideGui: (uuid) => WclapGuis.show(uuid, false),
            wclapStatus: (uuid, status) => {
                WclapFailures.report(project, uuid, this.#wclapStatus.get(uuid), status);
                this.#wclapStatus.set(uuid, status);
                for (const listener of this.#wclapStatusListeners.get(uuid)) {
                    listener(status);
                }
            },
            wclapRequestSave: (uuid) => this.wclapSaveState(UUID.parse(uuid)),
            notifyClipSequenceChanges: (changes) => {
                changes.stopped.forEach(uuid => {
                    for (let i = 0; i < this.#playingClips.length; i++) {
                        if (UUID.equals(this.#playingClips[i], uuid)) {
                            this.#playingClips.splice(i, 1);
                            break;
                        }
                    }
                });
                changes.started.forEach(uuid => this.#playingClips.push(uuid));
                this.#notifyClipNotification.notify({ type: "sequencing", changes });
            },
            switchMarkerState: (state) => this.#markerState.setValue(state),
            recordingStarted: (contextTime, position, generation) => {
                // a report for an earlier recording, delivered after the next one was prepared
                if (generation !== this.#recordingGeneration) {
                    return;
                }
                this.#recordingStart.wrap({ contextTime, position });
            },
            transportAnchors: (anchors) => {
                // the stop arrives here before the engine state is read on the next animation frame
                anchors.forEach(({ kind, recording, contextTime }) => {
                    if (kind === "stop" && recording) {
                        this.#recordingStop = Option.wrap({ contextTime });
                    }
                });
                this.#notifyTransportAnchors.notify(anchors);
            }
        });
        this.#preferences = this.#terminator.own(new PreferencesHost(EngineSettingsSchema.parse({})));
        const clockLease = this.#terminator.own(new Terminator());
        this.#terminator.ownAll(this.#preferences.catchupAndSubscribe(measure => {
            clockLease.terminate();
            if (measure) {
                clockLease.own(HRClockWorker.get().lease());
            }
        }, "debug", "dspLoadMeasurement"), AnimationFrame.add(() => reader.tryRead()), project.liveStreamReceiver.connect(messenger.channel("engine-live-data")), this.#preferences.syncWith(messenger.channel("engine-preferences")), variant.connectSync(messenger, project));
    }
    play() {
        this.wake();
        this.#commands.play();
    }
    stop(reset = false) { this.#commands.stop(reset); }
    setPosition(position) { this.#commands.setPosition(position); }
    prepareRecordingState(countIn) {
        this.#recordingGeneration++;
        this.#recordingStart.clear();
        this.#commands.prepareRecordingState(countIn, this.#recordingGeneration);
    }
    stopRecording() { this.#commands.stopRecording(); }
    panic() { this.#commands.panic(); }
    sleep() {
        Atomics.store(this.#controlFlags, 0, 1);
        this.#isPlaying.setValue(false);
        this.#commands.stop(true);
    }
    wake() { Atomics.store(this.#controlFlags, 0, 0); }
    loadClickSound(index, data) { this.#commands.loadClickSound(index, data); }
    wclapOpenGui(uuid) { return this.#commands.wclapOpenGui(uuid); }
    wclapCloseGui(uuid) { this.#commands.wclapCloseGui(uuid); }
    wclapOpenPanel(uuid, height) { return this.#commands.wclapOpenPanel(uuid, height); }
    wclapResizeGui(uuid, width, height) {
        return this.#commands.wclapResizeGui(uuid, width, height);
    }
    wclapReceive(uuid, bytes) { this.#commands.wclapReceive(uuid, bytes); }
    wclapSaveState(uuid) { this.#commands.wclapSaveState(uuid); }
    wclapDescribe(url) { return this.#commands.wclapDescribe(url); }
    wclapRetry(url) { this.#commands.wclapRetry(url); }
    scriptMessage(uuid, message) { this.#commands.scriptMessage(uuid, message); }
    overrideDeviceField(uuid, key, value) {
        this.#commands.overrideDeviceField(uuid, key, value);
    }
    querySignalGraph() { return this.#commands.querySignalGraph(); }
    setFrozenAudio(uuid, audioData) {
        if (isNull(this.#frozenAudioWriter)) {
            this.#commands.setFrozenAudio(uuid, audioData);
        }
        else {
            this.#frozenAudioWriter(uuid, audioData);
        }
    }
    get isPlaying() { return this.#isPlaying; }
    get isRecording() { return this.#isRecording; }
    get isCountingIn() { return this.#isCountingIn; }
    get countInBeatsRemaining() { return this.#countInBeatsRemaining; }
    get compensationLatency() { return this.#compensationLatency; }
    get compensationExceeded() { return this.#compensationExceeded; }
    get position() { return this.#position; }
    get recordingStart() { return this.#recordingStart; }
    get recordingStop() { return this.#recordingStop; }
    get bpm() { return this.#bpm; }
    get playbackTimestamp() { return this.#playbackTimestamp; }
    get markerState() { return this.#markerState; }
    get project() { return this.#project; }
    #describeNotice(notice) {
        const device = this.#labelOf(notice.device);
        switch (notice.type) {
            case "sidechain-loop":
                return `${device} listens to ${this.#labelOf(notice.source)}, which it feeds. This sidechain is a feedback loop.`;
            case "non-finite":
                return `${device} was reset because its output overflowed in a feedback loop.`;
        }
    }
    #labelOf(uuid) {
        const bytes = UUID.parse(uuid);
        const device = this.#project.boxGraph.findBox(bytes).flatMap(box => DeviceBoxUtils.isDeviceBox(box)
            ? Option.wrap(DeviceBoxUtils.lookupLabelField(box).getValue()) : Option.None);
        if (device.nonEmpty()) {
            return device.unwrap();
        }
        const find = (outputs) => {
            for (const output of outputs) {
                if (UUID.equals(output.address.uuid, bytes)) {
                    return Option.wrap(output.label);
                }
                const nested = output.children().flatMap(children => find(children));
                if (nested.nonEmpty()) {
                    return nested;
                }
            }
            return Option.None;
        };
        return find(this.#project.rootBoxAdapter.labeledAudioOutputs()).unwrapOrElse("A device");
    }
    get preferences() { return this.#preferences; }
    get cpuLoad() { return this.#cpuLoad; }
    get perfBuffer() { return this.#perfBuffer; }
    get perfIndex() { return this.#perfIndex; }
    isReady() { return this.#isReady; }
    queryLoadingComplete() { return this.#commands.queryLoadingComplete(); }
    noteSignal(signal) { this.#commands.noteSignal(signal); }
    subscribeNotes(observer) { return this.#notifyNoteSignals.subscribe(observer); }
    subscribeTransportAnchors(observer) {
        return this.#notifyTransportAnchors.subscribe(observer);
    }
    ignoreNoteRegion(uuid) { this.#commands.ignoreNoteRegion(uuid); }
    suspendAutomation(uuid) { this.#commands.suspendAutomation(uuid); }
    scheduleClipPlay(clipIds) {
        this.#notifyClipNotification.notify({ type: "waiting", clips: clipIds });
        this.#commands.scheduleClipPlay(clipIds);
    }
    scheduleClipStop(trackIds) {
        this.#commands.scheduleClipStop(trackIds);
    }
    subscribeClipNotification(observer) {
        observer({
            type: "sequencing",
            changes: { started: this.#playingClips, stopped: Arrays.empty(), obsolete: Arrays.empty() }
        });
        return this.#notifyClipNotification.subscribe(observer);
    }
    subscribeDeviceMessage(uuid, listener) {
        this.#deviceMessageListeners.add(uuid, listener);
        return { terminate: () => this.#deviceMessageListeners.remove(uuid, listener) };
    }
    // The plugin's load status, the last one replayed on subscribe
    subscribeWclapStatus(uuid, listener) {
        this.#wclapStatusListeners.add(uuid, listener);
        const current = this.#wclapStatus.get(uuid);
        if (isDefined(current)) {
            listener(current);
        }
        return { terminate: () => this.#wclapStatusListeners.remove(uuid, listener) };
    }
    registerMonitoringSource(uuid, node, numChannels, destinationNode) {
        this.#monitoringRouter.registerSource(uuid, node, numChannels, destinationNode);
    }
    unregisterMonitoringSource(uuid) {
        this.#monitoringRouter.unregisterSource(uuid);
    }
    #updateCpuLoad(budgetMs, project) {
        while (this.#lastPerfReadIndex !== this.#perfIndex) {
            const ms = this.#perfBuffer[this.#lastPerfReadIndex];
            if (ms > this.#maxMsSinceLastUpdate) {
                this.#maxMsSinceLastUpdate = ms;
            }
            if (ms >= budgetMs) {
                this.#consecutiveOverloadCount++;
                if (this.#consecutiveOverloadCount >= 30) {
                    project.handleCpuOverload();
                    this.#consecutiveOverloadCount = 0;
                }
            }
            else {
                this.#consecutiveOverloadCount = 0;
            }
            this.#lastPerfReadIndex = (this.#lastPerfReadIndex + 1) % PERF_BUFFER_SIZE;
        }
        const now = performance.now();
        if (now - this.#lastCpuLoadUpdate >= 1000) {
            this.#cpuLoad.setValue(Math.round((this.#maxMsSinceLastUpdate / budgetMs) * 100));
            this.#maxMsSinceLastUpdate = 0;
            this.#lastCpuLoadUpdate = now;
        }
    }
    terminate() {
        this.#commands.terminate();
        this.#terminator.terminate();
        this.disconnect();
    }
}
