import { asDefined, asInstanceOf, isInstanceOf, Option, RuntimeNotifier, Terminable, tryCatch, UUID } from "@opendaw/lib-std";
import { TrackBox } from "@opendaw/studio-boxes";
import { RegionOverlap, UnionBoxTypes } from "@opendaw/studio-adapters";
// Two participants can place or move regions onto one spot at the same time, each valid on its own client.
// Overlaps are never allowed, so one of the two changes is taken back as a whole: by the client that made it,
// because only it knows what it changed. Of two concurrent changes the client with the higher id gives way.
export var RoomOverlaps;
(function (RoomOverlaps) {
    const RegionNames = new Set(["NoteRegionBox", "AudioRegionBox", "ValueRegionBox"]);
    const regionOf = (graph, update) => {
        if (update.type === "new" || update.type === "delete") {
            return RegionNames.has(update.name) ? Option.wrap(update.uuid) : Option.None;
        }
        return graph.findBox(update.address.uuid)
            .flatMap(box => UnionBoxTypes.isRegionBox(box) ? Option.wrap(box.address.uuid) : Option.None);
    };
    const overlaps = (before, after) => {
        if (RegionOverlap.endsAtSuccessor(before)) {
            return false;
        }
        const position = after.position.getValue();
        return before.position.getValue() + before.duration.getValue() > position + RegionOverlap.boundaryTolerance(position);
    };
    RoomOverlaps.watch = (graph, sync) => {
        const latest = UUID.newSet(({ uuid }) => uuid);
        const pending = [];
        const touchedRegions = UUID.newSet(uuid => uuid);
        let known = Option.None;
        let take = false;
        let recording = false;
        let reverting = false;
        const writers = (region) => [region.address, region.position.address, region.duration.address, region.regions.address]
            .flatMap(address => sync.writerOf(address).mapOr(id => [id], []));
        const begin = () => {
            recording = !sync.applyingRemote && !reverting;
            take = sync.activeLayerKind.mapOr(kind => kind === "take", false);
            pending.length = 0;
            touchedRegions.clear();
            known = Option.None;
        };
        const record = (update) => {
            if (!recording) {
                return;
            }
            pending.push(update);
            regionOf(graph, update).ifSome(uuid => {
                if (known.isEmpty()) {
                    known = Option.wrap(sync.knownClocks());
                }
                touchedRegions.add(uuid);
            });
        };
        const end = (rolledBack) => {
            if (recording && !rolledBack && touchedRegions.size() > 0) {
                const change = { updates: pending.slice(), regions: touchedRegions.values(), known: known.unwrap(), take };
                change.regions.forEach(uuid => {
                    latest.removeByKeyIfExist(uuid);
                    latest.add({ uuid, change });
                });
            }
            recording = false;
            pending.length = 0;
            touchedRegions.clear();
        };
        const givesWay = (mine, other) => latest.opt(mine.address.uuid).mapOr(({ change }) => {
            const me = sync.clientID;
            if (!writers(mine).some(({ client }) => client === me)) {
                return false;
            }
            return writers(other).some(({ client, clock }) => client !== me && client < me && clock >= (change.known.get(client) ?? 0));
        }, false);
        const resolve = (touched) => {
            const tracks = new Set();
            touched.forEach(box => {
                if (isInstanceOf(box, TrackBox)) {
                    tracks.add(box);
                }
                if (UnionBoxTypes.isRegionBox(box)) {
                    box.regions.targetVertex.ifSome(vertex => { if (isInstanceOf(vertex.box, TrackBox)) {
                        tracks.add(vertex.box);
                    } });
                }
            });
            const losers = new Map();
            tracks.forEach(track => {
                if (!track.isAttached()) {
                    return;
                }
                const regions = RegionOverlap.sortedRegions(track).filter(region => !sync.isLocal(region.address.uuid));
                regions.forEach((before, index) => regions.slice(index + 1).forEach(after => {
                    if (!overlaps(before, after)) {
                        return;
                    }
                    if (givesWay(before, after)) {
                        losers.set(UUID.toString(before.address.uuid), before);
                    }
                    if (givesWay(after, before)) {
                        losers.set(UUID.toString(after.address.uuid), after);
                    }
                }));
            });
            if (losers.size === 0) {
                return;
            }
            // a recording is never taken back, it moves to a track of its own
            const takes = Array.from(losers.values()).filter(region => latest.get(region.address.uuid).change.take);
            const changes = new Set();
            losers.forEach(region => {
                const { change } = latest.get(region.address.uuid);
                if (!change.take) {
                    changes.add(change);
                }
            });
            takes.forEach(region => latest.removeByKey(region.address.uuid));
            changes.forEach(change => change.regions.forEach(uuid => {
                if (latest.opt(uuid).mapOr(entry => entry.change === change, false)) {
                    latest.removeByKey(uuid);
                }
            }));
            reverting = true;
            graph.beginTransaction();
            const result = tryCatch(() => {
                changes.forEach(change => takeBack(change));
                losers.forEach(region => { if (takes.includes(region) || stillOverlaps(region)) {
                    moveBelow(region);
                } });
                graph.endTransaction();
            });
            if (result.status === "failure") {
                console.warn("[RoomOverlaps] could not take back the whole change, removing the region instead:", result.error);
                if (graph.inTransaction()) {
                    graph.abortTransaction();
                }
                graph.beginTransaction();
                losers.forEach(region => { if (region.isAttached()) {
                    region.delete();
                } });
                graph.endTransaction();
            }
            reverting = false;
            RuntimeNotifier.notify({
                message: changes.size === 0
                    ? "Another participant used the same spot at the same time. Your recording moved to a track of its own."
                    : "Another participant used the same spot at the same time. Your change was taken back.",
                icon: "Info"
            });
        };
        const stillOverlaps = (region) => region.isAttached() && region.regions.targetVertex
            .mapOr(({ box }) => isInstanceOf(box, TrackBox) && RegionOverlap.sortedRegions(box)
            .some(other => other !== region && (other.position.getValue() <= region.position.getValue()
            ? overlaps(other, region) : overlaps(region, other))), false);
        // a new track of the same kind right below every track of the owner
        const moveBelow = (region) => region.regions.targetVertex.ifSome(({ box }) => {
            const track = asInstanceOf(box, TrackBox);
            const owner = track.tracks.targetVertex.unwrap("track without owner");
            const index = owner.pointerHub.incoming().reduce((max, { box }) => Math.max(max, asInstanceOf(box, TrackBox).index.getValue() + 1), 0);
            const below = TrackBox.create(graph, UUID.generate(), created => {
                created.type.setValue(track.type.getValue());
                created.index.setValue(index);
                created.tracks.refer(owner);
                track.target.targetVertex.ifSome(target => created.target.refer(target));
            });
            region.regions.refer(below.regions);
        });
        const mine = (address) => sync.writerOf(address).mapOr(({ client }) => client === sync.clientID, false);
        // like an undo, but what a peer wrote since stays, and so does a new box a peer already points at
        const takeBack = (change) => {
            const created = UUID.newSet(uuid => uuid);
            change.updates.forEach(update => { if (update.type === "new") {
                created.add(update.uuid);
            } });
            const kept = UUID.newSet(uuid => uuid);
            const keep = [];
            created.forEach(uuid => graph.findBox(uuid).ifSome(box => {
                // a pointer this client wrote is part of the change, only a peer's pointer is a dependency
                if (box.incomingEdges().some(pointer => !created.hasKey(pointer.box.address.uuid) && !mine(pointer.address))) {
                    keep.push(box);
                }
            }));
            // what a kept box is connected to within the change stays with it
            while (keep.length > 0) {
                const box = asDefined(keep.pop());
                if (!kept.add(box.address.uuid)) {
                    continue;
                }
                box.outgoingEdges().forEach(([, target]) => graph.findBox(target.uuid).ifSome(other => {
                    if (created.hasKey(other.address.uuid)) {
                        keep.push(other);
                    }
                }));
                box.incomingEdges().forEach(({ box: other }) => { if (created.hasKey(other.address.uuid)) {
                    keep.push(other);
                } });
            }
            change.updates.toReversed().forEach(update => {
                if (update.type === "new") {
                    if (kept.hasKey(update.uuid)) {
                        return;
                    }
                    graph.findBox(update.uuid).ifSome(box => { if (mine(box.address)) {
                        update.inverse(graph);
                    } });
                }
                else if (update.type === "delete") {
                    if (graph.findBox(update.uuid).isEmpty()) {
                        update.inverse(graph);
                    }
                }
                else if (!kept.hasKey(update.address.uuid) && graph.findVertex(update.address).nonEmpty() && mine(update.address)) {
                    update.inverse(graph);
                }
            });
        };
        const terminables = [
            graph.subscribeToAllUpdates({ onUpdate: record }),
            graph.subscribeTransaction({ onBeginTransaction: begin, onEndTransaction: end }),
            sync.subscribeRemote(resolve)
        ];
        return Terminable.many(...terminables);
    };
})(RoomOverlaps || (RoomOverlaps = {}));
