import { migrateDelayDeviceBox } from "./MigrateDelayDeviceBox";
import { migrateArpeggioDeviceBox } from "./MigrateArpeggioDeviceBox";
// Shared by the project migration and the preset decoder, so old presets never enter a project unmigrated.
export var DeviceMigration;
(function (DeviceMigration) {
    DeviceMigration.visitor = (boxGraph) => ({
        visitDelayDeviceBox: (box) => migrateDelayDeviceBox(boxGraph, box),
        visitArpeggioDeviceBox: (box) => migrateArpeggioDeviceBox(boxGraph, box)
    });
    DeviceMigration.migrate = (boxGraph) => {
        const visitor = DeviceMigration.visitor(boxGraph);
        boxGraph.boxes().slice().forEach(box => box.accept(visitor));
    };
})(DeviceMigration || (DeviceMigration = {}));
