import { moebiusEase, squashUnit } from "@opendaw/lib-std";
import { GrooveDurations } from "./GrooveDurations";
import { CellGrooveBoxAdapter } from "./CellGrooveBoxAdapter";
export class GrooveShuffleBoxAdapter extends CellGrooveBoxAdapter {
    constructor(context, box) {
        super(context, box);
        this.namedParameter = { amount: this.amountParameter, duration: this.durationParameter };
    }
    get kind() { return "shuffle"; }
    createFunction() {
        const amount = squashUnit(this.box.amount.getValue(), 0.01);
        return { fx: phase => moebiusEase(phase, amount), fy: phase => moebiusEase(phase, 1.0 - amount) };
    }
}
GrooveShuffleBoxAdapter.Durations = GrooveDurations.Signatures;
GrooveShuffleBoxAdapter.DurationPPQNs = GrooveDurations.PPQNs;
GrooveShuffleBoxAdapter.DurationStrings = GrooveDurations.Labels;
