type Construct = {
    element: Element
    service: StudioService
    capturing: ElementCapturing<RegionCaptureTarget>
    selection: Selection<AnyRegionBoxAdapter>
    timelineBox: TimelineBox
    range: TimelineRange
}

const computeSelectionRange = (selection: Selection<AnyRegionBoxAdapter>): [ppqn, ppqn] =>
    selection.selected().reduce<[ppqn, ppqn]>((range, region) => {
        range[0] = Math.min(region.position, range[0])
        range[1] = Math.max(region.complete, range[1])
        return range
    }, [Number.MAX_VALUE, -Number.MAX_VALUE])

export const loopRegionSelection = (editing: Editing, timelineBox: TimelineBox,
                                    selection: Selection<AnyRegionBoxAdapter>): boolean => {
    if (selection.isEmpty()) {return false}
    const [min, max] = computeSelectionRange(selection)
    editing.modify(() => {
        timelineBox.loopArea.from.setValue(min)
        timelineBox.loopArea.to.setValue(max)
        timelineBox.loopArea.enabled.setValue(true)
    })
    return true
}

export const installRegionContextMenu =
    ({element, service, capturing, selection, timelineBox, range}: Construct): Terminable => {
        const {project} = service
        const {editing, selection: vertexSelection} = project
        return ContextMenu.subscribe(element, ({addItems, closeWhen, client}: ContextMenu.Collector) => {
            const target = capturing.captureEvent(client)
            if (target === null || target.type === "track") {return}
            if (!selection.isSelected(target.region)) {
                selection.deselectAll()
                selection.select(target.region)
            }
            const region = target.region
            closeWhen(close => region.box.subscribeDeletion(close))
            addItems(
                MenuItem.default({label: "Delete", shortcut: "⌫"})
                    .setTriggerProcedure(() => editing.modify(() => selection.selected().slice()
                        .forEach(adapter => adapter.box.delete()))),
                MenuItem.default({label: "Duplicate"})
                    .setTriggerProcedure(() => editing.modify(() => {
                        project.api.duplicateRegion(region)
                            .ifSome(duplicate => {
                                selection.deselectAll()
                                selection.select(duplicate)
                            })
                    })),
                MenuItem.default({
                    label: "Mute",
                    checked: region.mute,
                    shortcut: RegionsShortcuts["toggle-mute"].shortcut.format()
                }).setTriggerProcedure(() => editing.modify(() => {
                    const newValue = !region.mute
                    return selection.selected().slice().forEach(adapter => adapter.box.mute.setValue(newValue))
                })),
                ColorMenu.createItem(hue => editing.modify(() =>
                    selection.selected().slice().forEach(adapter => adapter.box.hue.setValue(hue)))),
                GrooveMenus.timelineItem(project, selection.selected().map(adapter => adapter.box)),
                MenuItem.default({label: "Rename"})
                    .setTriggerProcedure(() => Surface.get(element).requestFloatingTextInput(client, region.label)
                        .then(value => NameValidator.validate(value, {
                            success: name => editing.modify(() => selection.selected()
                                .forEach(adapter => adapter.box.label.setValue(name)))
                        }), EmptyExec)),
                MenuItem.default({
                    label: "Loop Selection",
                    shortcut: RegionsShortcuts["loop-selection"].shortcut.format()
                }).setTriggerProcedure(() => loopRegionSelection(editing, timelineBox, selection)),
                MenuItem.default({label: "Zoom Selection"})
                    .setTriggerProcedure(() => {
                        const [min, max] = computeSelectionRange(selection)
                        range.zoomRange(min, max)
                    }),
                MenuItem.default({
                    label: "Consolidate",
                    selectable: selection.selected().some(x => x.isMirrowed),
                    separatorBefore: true
                }).setTriggerProcedure(() => editing.modify(() => selection.selected().slice()
                    .forEach(adapter => adapter.consolidate()))),
                MenuItem.default({label: "Flatten", selectable: region.canFlatten(selection.selected())})
                    .setTriggerProcedure(() => {
                        if (region instanceof AudioRegionBoxAdapter) {
                            const audioRegions = selection.selected()
                                .filter((adapter): adapter is AudioRegionBoxAdapter =>
                                    isInstanceOf(adapter, AudioRegionBoxAdapter))
                            AudioConsolidation.flatten(project, service.sampleService, audioRegions)
                                .then(EmptyExec, console.warn)
                        } else {
                            const {truncateNotesAtRegionEnd} = service.engine.preferences.settings.playback
                            const regions = selection.selected().slice()
                            const flatten = (groove: Grooves.FlattenGroove) => editing.modify(() =>
                                region.flatten(regions, truncateNotesAtRegionEnd, groove)
                                    .ifSome(box => project.selection.select(box)))
                            const grooved = regions.some(adapter =>
                                Grooves.pointerOf(adapter.box).flatMap(pointer => pointer.targetVertex).nonEmpty())
                            if (!grooved) {
                                flatten("keep")
                                return
                            }
                            // a region deleted meanwhile (undo, a peer) closes the dialog and nothing is flattened
                            const deleted = new AbortController()
                            const watches = [...regions, region].map(adapter => adapter.box.subscribeDeletion(() => deleted.abort()))
                            Dialogs.choose<Grooves.FlattenGroove | "cancel">({
                                headline: "Flatten Grooved Regions",
                                message: "Apply Groove moves the notes and automation points to where the groove plays them, the region sounds the same. Keep Groove leaves them in place and keeps the groove only when all regions share it, it then starts at the new region start.",
                                choices: [
                                    {text: "Cancel", value: "cancel"},
                                    {text: "Keep Groove", value: "keep"},
                                    {text: "Apply Groove", value: "apply"}
                                ],
                                origin: element,
                                abortSignal: deleted.signal
                            }).then(choice => {
                                watches.forEach(watch => watch.terminate())
                                choice.ifSome(groove => {if (groove !== "cancel") {flatten(groove)}})
                            }, EmptyExec)
                        }
                    }),
                MenuItem.default({label: "Detect Chords", hidden: region.type !== "note-region"})
                    .setTriggerProcedure(() => HarmonyDetection.detectChords(service,
                        HarmonyDetection.fromRegions(selection.selected()))),
                MenuItem.default({label: "Detect Key", hidden: region.type !== "note-region"})
                    .setTriggerProcedure(() => HarmonyDetection.detectKey(service,
                        HarmonyDetection.fromRegions(selection.selected()))),
                MenuItem.default({label: "Bounce...", selectable: AudioBounce.canBounce(selection.selected())})
                    .setTriggerProcedure(() => Bounces.bounceRegions(service, selection.selected().slice())
                        .then(EmptyExec, console.warn)),
                MenuItem.default({
                    label: "Convert to Mono...",
                    hidden: region.type !== "audio-region",
                    selectable: isInstanceOf(region, AudioRegionBoxAdapter) && AudioMonoConversion.canConvert(region.file)
                }).setTriggerProcedure(() => {
                    if (isInstanceOf(region, AudioRegionBoxAdapter)) {
                        MonoConversions.convertRegion(service, region).then(EmptyExec, console.warn)
                    }
                }),
                MenuItem.default({label: "Edit in Sample Editor", hidden: region.type !== "audio-region"})
                    .setTriggerProcedure(() => {
                        if (isInstanceOf(region, AudioRegionBoxAdapter)) {
                            service.sampleEditor.openFile(region.file).then(EmptyExec, console.warn)
                        }
                    }),
                MenuItem.default({label: "Convert to Clip"})
                    .setTriggerProcedure(() => region.trackBoxAdapter.ifSome(() => editing.modify(() => {
                        service.timeline.clips.visible.setValue(true)
                        const clip = RegionTransformer.toClip(region)
                        vertexSelection.select(clip)
                        project.userEditingManager.timeline.edit(clip)
                    }))),
                MenuItem.default({
                    label: "Export to Midi-File",
                    hidden: region.type !== "note-region"
                }).setTriggerProcedure(() => {
                    if (region.type === "note-region") {
                        const label = region.label
                        NoteMidiExport.toFile(region.optCollection.unwrap("optCollection"),
                            `${label.length === 0 ? "region" : label}.mid`).then(EmptyExec, EmptyExec)
                    }
                }),
                MenuItem.default({
                    label: "Reset Fades",
                    hidden: region.type !== "audio-region"
                }).setTriggerProcedure(() => {
                    if (isInstanceOf(region, AudioRegionBoxAdapter)) {
                        editing.modify(() => region.fading.reset())
                    }
                }),
                MenuItem.default({
                    label: "Play Mode",
                    hidden: region.type !== "audio-region"
                }).setRuntimeChildrenProcedure(parent => parent.addMenuItem(
                    MenuItem.default({
                        label: "Pitch",
                        checked: region.type === "audio-region" && region.asPlayModePitchStretch.nonEmpty()
                    }).setTriggerProcedure(async () => {
                        const {status, value: modifier, error} =
                            await Promises.tryCatch(AudioContentModifier.toPitchStretch(selection.selected()
                                .filter((region): region is AudioRegionBoxAdapter => region.type === "audio-region")))
                        if (status === "resolved") {
                            editing.modify(modifier)
                        } else {
                            console.warn(error)
                        }
                    }),
                    MenuItem.default({
                        label: "Timestretch",
                        checked: region.type === "audio-region" && region.asPlayModeTimeStretch.nonEmpty()
                    }).setTriggerProcedure(async () => {
                        const {status, value: modifier, error} =
                            await Promises.tryCatch(AudioContentModifier.toTimeStretch(selection.selected()
                                .filter((region): region is AudioRegionBoxAdapter => region.type === "audio-region")))
                        if (status === "resolved") {
                            editing.modify(modifier)
                        } else {
                            console.warn(error)
                        }
                    }),
                    MenuItem.default({
                        label: "No Warp",
                        checked: region.type === "audio-region" && region.isPlayModeNoStretch
                    }).setTriggerProcedure(async () => {
                            const {status, value: modifier, error} =
                                await Promises.tryCatch(AudioContentModifier.toNotStretched(selection.selected()
                                    .filter((region): region is AudioRegionBoxAdapter => region.type === "audio-region")))
                            if (status === "resolved") {
                                editing.modify(modifier)
                            } else {
                                console.warn(error)
                            }
                        }
                    )
                )),
                MenuItem.default({
                    label: "Detect BPM (AI)...",
                    hidden: region.type !== "audio-region" || !Browser.isLocalHost()
                }).setTriggerProcedure(() => {
                    if (region.type === "audio-region") {
                        region.file.data.ifSome(async data => {
                            const bpm = await TempoDetection.runOne(data.frames[0], data.sampleRate, region.label)
                            // null is cancel or failure, both of which runOne has already reported.
                            if (isNull(bpm)) {return}
                            await RuntimeNotifier.info({headline: region.label, message: `${bpm} bpm`})
                        })
                    }
                }),
                MenuItem.default({
                    label: "Analyze Material...",
                    hidden: region.type !== "audio-region" || !Browser.isLocalHost()
                }).setTriggerProcedure(() => {
                    if (region.type === "audio-region") {
                        region.file.data.ifSome(async data => {
                            const label = region.label.length === 0 ? "Audio" : region.label
                            const updater = RuntimeNotifier.progress({headline: "Analyzing material", message: label})
                            const {status, value, error} =
                                await Promises.tryCatch(service.materialAnalyzer.analyze(data))
                            updater.terminate()
                            if (status === "rejected") {
                                console.warn(error)
                                RuntimeNotifier.notify({message: "Could not analyze material.", icon: "Warning"})
                                return
                            }
                            await AudioMaterialDialog.show(label, value, element)
                        })
                    }
                }),
                DebugMenus.debugBox(region.box)
            )
        })
    }
