import { StringMapping, ValueMapping } from "@opendaw/lib-std";
import { GrooveCurves, QuantisedGrooveFunction } from "@opendaw/lib-dsp";
import { CellGrooveBoxAdapter } from "./CellGrooveBoxAdapter";
export class GrooveRandomBoxAdapter extends CellGrooveBoxAdapter {
    constructor(context, box) {
        super(context, box);
        this.roughness = this.parametric.createParameter(box.roughness, ValueMapping.unipolar(), StringMapping.percent({ fractionDigits: 0 }), "Roughness");
        this.steps = this.parametric.createParameter(box.steps, ValueMapping.linearInteger(2, 64), StringMapping.numeric({ fractionDigits: 0 }), "Steps");
    }
    get kind() { return "random"; }
    reseed() { this.box.seed.setValue(1 + Math.floor(Math.random() * GrooveRandomBoxAdapter.MaxSeed)); }
    createFunction() {
        const { seed, steps, roughness, amount } = this.box;
        const values = GrooveCurves.randomValues(seed.getValue(), steps.getValue(), roughness.getValue());
        return GrooveCurves.blend(new QuantisedGrooveFunction(values), amount.getValue());
    }
}
GrooveRandomBoxAdapter.MaxSeed = 999999;
