import { Option, Terminable, VitalSigns } from "@opendaw/lib-std";
import { Promises } from "@opendaw/lib-runtime";
import { Capture } from "./Capture";
import { InputLatency } from "./InputLatency";
import { RecordAudio } from "./RecordAudio";
import { BrowserAudioInput, ChannelMapping } from "../io";
export class CaptureAudio extends Capture {
    #vitalSigns;
    #input;
    #streamGenerator;
    #requestChannels = Option.None;
    #mapping = Option.None;
    #gainDb = 0.0;
    constructor(manager, audioUnitBox, captureAudioBox, createInput = request => new BrowserAudioInput(manager.project, audioUnitBox.address.uuid, request)) {
        super(manager, audioUnitBox, captureAudioBox);
        this.#vitalSigns = this.own(new VitalSigns());
        this.#input = createInput(() => this.#request());
        this.#streamGenerator = Promises.sequentialize(() => this.#input.open());
        const remap = async () => {
            const left = captureAudioBox.leftInputs.getValue();
            const right = captureAudioBox.rightInputs.getValue();
            this.#mapping = left === 0 && right === 0 ? Option.None : Option.wrap({ left, right });
            this.#input.rechannel();
            if (this.armed.getValue()) {
                await this.#streamGenerator();
            }
        };
        this.ownAll(this.#input, captureAudioBox.requestChannels.catchupAndSubscribe(owner => {
            const channels = owner.getValue();
            this.#requestChannels = channels === 1 || channels === 2 ? Option.wrap(channels) : Option.None;
            this.#input.rechannel();
        }), captureAudioBox.leftInputs.catchupAndSubscribe(remap), captureAudioBox.rightInputs.subscribe(remap), captureAudioBox.gainDb.catchupAndSubscribe(owner => {
            this.#gainDb = owner.getValue();
            this.#input.gainDb = this.#gainDb;
        }), captureAudioBox.deviceId.catchupAndSubscribe(async () => {
            if (this.armed.getValue()) {
                await this.#streamGenerator();
            }
        }), this.armed.catchupAndSubscribe(async (owner) => {
            const armed = owner.getValue();
            if (armed) {
                await this.#streamGenerator();
            }
            else {
                this.#input.close();
            }
        }));
    }
    get input() { return this.#input; }
    get isMonitoring() { return this.#input.monitor.mode !== "off"; }
    get monitoringMode() { return this.#input.monitor.mode; }
    set monitoringMode(value) {
        if (this.#input.monitor.mode === value) {
            return;
        }
        this.#input.monitor.mode = value;
        if (value !== "off") {
            this.armed.setValue(true);
        }
    }
    get gainDb() { return this.#gainDb; }
    get requestChannels() { return this.#requestChannels; }
    set requestChannels(value) {
        this.captureBox.requestChannels.setValue(value);
        this.captureBox.leftInputs.setValue(0);
        this.captureBox.rightInputs.setValue(0);
    }
    get channelMapping() {
        return this.#mapping.unwrapOrElse(() => this.#requestChannels
            .mapOr(channels => channels === 1 ? ChannelMapping.MonoMixed : ChannelMapping.Stereo, ChannelMapping.Stereo));
    }
    // the two mappings a channel count stands for are kept as that count
    set channelMapping(mapping) {
        const counted = ChannelMapping.equals(mapping, ChannelMapping.Stereo)
            || ChannelMapping.equals(mapping, ChannelMapping.MonoMixed);
        this.captureBox.requestChannels.setValue(ChannelMapping.outputCount(mapping));
        this.captureBox.leftInputs.setValue(counted ? 0 : mapping.left);
        this.captureBox.rightInputs.setValue(counted ? 0 : mapping.right);
    }
    get stream() { return this.#nodes().stream; }
    get streamDeviceId() { return this.#input.deviceId; }
    get label() { return this.#input.label.unwrapOrElse("Default"); }
    get deviceLabel() { return this.#input.label; }
    get streamMediaTrack() { return this.#input.nodes.flatMap(nodes => nodes.streamMediaTrack); }
    get outputNode() { return this.#input.nodes.flatMap(nodes => nodes.outputNode); }
    subscribeOutputNode(observer) {
        return this.#input.nodes.mapOr(nodes => nodes.subscribeOutputNode(observer), Terminable.Empty);
    }
    get effectiveChannelCount() { return this.#input.channelCount; }
    get monitorGainNode() { return this.#nodes().monitorGainNode; }
    get monitorPanNode() { return this.#nodes().monitorPanNode; }
    get monitorVolumeDb() { return this.#input.monitor.volumeDb; }
    set monitorVolumeDb(value) { this.#input.monitor.volumeDb = value; }
    get monitorPan() { return this.#input.monitor.pan; }
    set monitorPan(value) { this.#input.monitor.pan = value; }
    get monitorMuted() { return this.#input.monitor.muted; }
    set monitorMuted(value) { this.#input.monitor.muted = value; }
    get monitorOutputDeviceId() { return this.#input.monitor.outputDeviceId; }
    setMonitorOutputDevice(deviceId) { return this.#input.monitor.setOutputDevice(deviceId); }
    prepareRecording() { return this.#input.prepareRecording(() => this.#streamGenerator()); }
    // the measured round trip replaces both reported latencies, unless this track overrides its input latency
    get roundTrip() { return this.#input.roundTrip; }
    forgetRoundTrip() { this.#input.forgetRoundTrip(); }
    subscribeRoundTrip(observer) { return this.#input.subscribeRoundTrip(observer); }
    async measureRoundTrip() {
        const { engine } = this.manager.project;
        if (engine.isPlaying.getValue() || engine.isRecording.getValue()) {
            return Promise.reject("Stop the transport to measure the latency.");
        }
        this.armed.setValue(true);
        await this.#streamGenerator();
        return this.#input.measureRoundTrip();
    }
    startRecording() {
        const { project } = this.manager;
        const { env: { sampleManager }, engine } = project;
        return this.#input.takeRecording().match({
            none: () => {
                console.warn("No audio chain or worklet available for recording.");
                return Terminable.Empty;
            },
            some: sink => RecordAudio.start({
                sink, sampleManager, project, capture: this,
                readLatency: this.#input.readLatency(outputLatency => InputLatency.resolve(this.captureBox.inputLatency.getValue(), engine.preferences.settings.recording.inputLatency, outputLatency), this.captureBox.inputLatency.getValue() <= InputLatency.Inherit)
            })
        });
    }
    #request() {
        if (!this.armed.getValue() || this.#vitalSigns.isTerminated) {
            return Option.None;
        }
        return Option.wrap({ deviceId: this.deviceId.getValue(), channels: this.#requestChannels, mapping: this.#mapping });
    }
    #nodes() { return this.#input.nodes.unwrap("The audio input has no Web Audio nodes"); }
}
