import { isDefined, Notifier } from "@opendaw/lib-std";
// Open plugin webviews by device uuid: the engine's `wclapSend` lands in every registered receiver
export var WclapGuis;
(function (WclapGuis) {
    const guis = new Map();
    WclapGuis.register = (uuid, receiver) => {
        const receivers = guis.get(uuid) ?? new Set();
        receivers.add(receiver);
        guis.set(uuid, receivers);
        return {
            terminate: () => {
                const current = guis.get(uuid);
                if (!isDefined(current) || !current.delete(receiver) || current.size > 0) {
                    return;
                }
                guis.delete(uuid);
                hovered.delete(uuid);
            }
        };
    };
    WclapGuis.deliver = (uuid, bytes) => guis.get(uuid)?.forEach(receiver => receiver(bytes));
    // clap.param-hovered per device, -1 = none
    const hovered = new Map();
    const notifier = new Notifier();
    WclapGuis.hover = (uuid, paramId) => {
        hovered.set(uuid, paramId);
        notifier.notify({ uuid, paramId });
    };
    WclapGuis.hoveredParam = (uuid) => hovered.get(uuid) ?? -1;
    WclapGuis.subscribeHovered = (uuid, procedure) => notifier.subscribe(event => { if (event.uuid === uuid) {
        procedure(event.paramId);
    } });
    // clap.gui request_resize per device
    const resizes = new Notifier();
    WclapGuis.resize = (uuid, width, height) => resizes.notify({ uuid, size: { width, height } });
    WclapGuis.subscribeResize = (uuid, procedure) => resizes.subscribe(event => { if (event.uuid === uuid) {
        procedure(event.size);
    } });
    // clap.gui request_show (true) and request_hide (false) per device
    const shows = new Notifier();
    WclapGuis.show = (uuid, visible) => shows.notify({ uuid, visible });
    WclapGuis.subscribeShow = (uuid, procedure) => shows.subscribe(event => { if (event.uuid === uuid) {
        procedure(event.visible);
    } });
})(WclapGuis || (WclapGuis = {}));
