import { Option } from "@opendaw/lib-std";
import { RecordingSession } from "./RecordingSession";
// facade over the project's RecordingSession, kept for SDK consumers
export class Recording {
    static get isRecording() { return RecordingSession.anyRecording; }
    static async start(project, countIn) {
        this.#last = Option.wrap(project.recordingSession);
        return project.recordingSession.start(countIn);
    }
    static #last = Option.None;
    static wasCountingIn() { return this.#last.mapOr(session => session.wasCountingIn, false); }
    static wasStartingAt() { return this.#last.mapOr(session => session.startPosition, 0.0); }
}
