import { Color } from "@opendaw/lib-std";
export const ColorSchemes = ["classic", "modern", "contrast"];
export const DefaultColorScheme = "classic";
const NeutralHue = 197;
const Neutrals = {
    classic: {
        bright: [5, 100], gray: [31, 91], dark: [15, 84], shadow: [10, 60], black: [10, 30],
        background: [8, 9], panelBackground: [14, 12], panelBackgroundBright: [13, 16], panelBackgroundDark: [14, 11],
        headerBackground: [14, 3], footerBackground: [14, 9]
    },
    modern: {
        bright: [0, 100], gray: [0, 70], dark: [0, 58], shadow: [0, 39], black: [0, 24],
        background: [0, 13], panelBackground: [0, 15], panelBackgroundBright: [0, 20], panelBackgroundDark: [0, 12],
        headerBackground: [0, 18], footerBackground: [0, 11]
    },
    contrast: {
        bright: [10, 100], gray: [10, 96], dark: [10, 90], shadow: [10, 76], black: [10, 58],
        background: [10, 4], panelBackground: [10, 9], panelBackgroundBright: [10, 16], panelBackgroundDark: [10, 6],
        headerBackground: [10, 3], footerBackground: [10, 5]
    }
};
let scheme = DefaultColorScheme;
const neutral = (name) => {
    const [saturation, lightness] = Neutrals[scheme][name];
    return new Color(NeutralHue, saturation, lightness);
};
export const Colors = {
    white: new Color(0, 0, 100),
    blue: new Color(189, 100, 65),
    green: new Color(150, 77, 69),
    yellow: new Color(60, 100, 84),
    cream: new Color(65, 37, 83),
    orange: new Color(31, 100, 73),
    red: new Color(354, 100, 65),
    purple: new Color(314, 100, 78),
    menuActive: new Color(210, 90, 40),
    get bright() { return neutral("bright"); },
    get gray() { return neutral("gray"); },
    get dark() { return neutral("dark"); },
    get shadow() { return neutral("shadow"); },
    get black() { return neutral("black"); },
    get background() { return neutral("background"); },
    get panelBackground() { return neutral("panelBackground"); },
    get panelBackgroundBright() { return neutral("panelBackgroundBright"); },
    get panelBackgroundDark() { return neutral("panelBackgroundDark"); },
    get headerBackground() { return neutral("headerBackground"); },
    get footerBackground() { return neutral("footerBackground"); }
};
export const setColorScheme = (value) => { scheme = value; };
export const initializeColors = (root) => {
    Object.entries(Colors).forEach(([name, value]) => {
        const cssName = name.replace(/([A-Z])/g, "-$1").toLowerCase();
        root.style.setProperty(`--color-${cssName}`, value.toString());
    });
};
