import { EmptyExec, Errors, Option, Terminable, Terminator, TimeSpan, UUID } from "@opendaw/lib-std";
import { Promises, Runtime } from "@opendaw/lib-runtime";
import { RecordAutomation } from "./RecordAutomation";
import { RoomTake } from "./RoomTake";
const PublishTimeout = TimeSpan.seconds(60);
// in a live room everything a recording writes stays on this client until the take is finished and its audio saved
class TakeScope {
    settle;
    #editing;
    #layer;
    #holds = 0;
    #finished = false;
    constructor(editing, layer, settle) {
        this.settle = settle;
        this.#editing = editing;
        this.#layer = layer;
    }
    #run(procedure) { return this.#layer.mapOr(layer => layer.run(procedure), procedure); }
    modify(modifier, mark) {
        return this.#run(() => this.#editing.modify(modifier, mark));
    }
    append(modifier) { return this.#run(() => this.#editing.append(modifier)); }
    mark() { this.#editing.mark(); }
    canUndo() { return this.#editing.canUndo(); }
    canRedo() { return this.#editing.canRedo(); }
    undo() { return this.#editing.undo(); }
    redo() { return this.#editing.redo(); }
    markSaved() { this.#editing.markSaved(); }
    hasUnsavedChanges() { return this.#editing.hasUnsavedChanges(); }
    hasNoChanges() { return this.#editing.hasNoChanges(); }
    revertPending() { this.#editing.revertPending(); }
    subscribe(observer) { return this.#editing.subscribe(observer); }
    hold() {
        if (this.#layer.isEmpty()) {
            return EmptyExec;
        }
        this.#holds++;
        let released = false;
        return () => {
            if (released) {
                return;
            }
            released = true;
            this.#holds--;
            this.#publishIfReady();
        };
    }
    finish() {
        this.#finished = true;
        this.#publishIfReady();
        if (this.#layer.nonEmpty()) {
            Runtime.scheduleTimeout(() => this.#publish(), PublishTimeout.millis());
        }
    }
    #publishIfReady() { if (this.#finished && this.#holds === 0) {
        this.#publish();
    } }
    #publish() {
        this.#layer.ifSome(layer => {
            this.settle();
            layer.publish();
            layer.terminate();
        });
        this.#layer = Option.None;
    }
}
// one recording at a time per project: arms the captures, drives the engine, finalizes on the engine's stop
export class RecordingSession {
    static #active = 0;
    // any project records
    static get anyRecording() { return this.#active > 0; }
    #project;
    #take = Option.None;
    #isRecording = false;
    #countIn = false;
    #startPosition = 0.0;
    constructor(project) { this.#project = project; }
    get isRecording() { return this.#isRecording; }
    get wasCountingIn() { return this.#countIn; }
    get startPosition() { return this.#startPosition; }
    // what recorders write through, outside a live room this is the project's editing
    get editing() { return this.#take.mapOr(take => take, this.#project.editing); }
    // the take reaches the room only after every hold is released
    holdPublish() { return this.#take.match({ none: () => EmptyExec, some: take => take.hold() }); }
    async start(countIn) {
        if (this.#isRecording || this.#project.engine.transportLocked.getValue()) {
            return Terminable.Empty;
        }
        this.#setRecording(true);
        const project = this.#project;
        const { captureDevices, engine } = project;
        const terminator = new Terminator();
        const captures = captureDevices.filterArmed();
        const layer = project.liveSync.map(sync => sync.createLayer("take"));
        const take = new TakeScope(project.editing, layer, () => layer.ifSome(layer => RoomTake.settle(project, layer)));
        this.#take = Option.wrap(take);
        if (captures.length > 0) {
            const { status, error } = await Promises.tryCatch(Promise.all(captures.map(capture => capture.prepareRecording())));
            if (status === "rejected") {
                layer.ifSome(layer => layer.terminate());
                this.#take = Option.None;
                this.#setRecording(false);
                return Errors.warn(String(error));
            }
            captures.forEach(capture => capture.clearRecordedRegions());
            terminator.ownAll(...captures.map(capture => capture.startRecording()));
        }
        if (engine.preferences.settings.recording.automationEnabled) {
            terminator.own(RecordAutomation.start(project));
        }
        const armedUUIDs = UUID.newSet(uuid => uuid);
        captures.forEach(capture => armedUUIDs.add(capture.audioUnitBox.address.uuid));
        project.regionSelection.deselect(...project.regionSelection.selected()
            .filter(region => region.trackBoxAdapter
            .mapOr(track => track.optAudioUnit
            .mapOr(unit => armedUUIDs.hasKey(unit.address.uuid), false), () => false)));
        engine.prepareRecordingState(countIn);
        const { isRecording, isCountingIn } = engine;
        let finished = false;
        const finish = () => {
            if (finished) {
                return;
            }
            finished = true;
            take.modify(() => terminator.terminate(), false); // finalizes recording
            if (layer.nonEmpty()) {
                take.mark();
            } // in a room every take is its own undo step
            this.#setRecording(false);
            take.finish();
        };
        const stop = () => {
            if (isRecording.getValue() || isCountingIn.getValue()) {
                return;
            }
            finish();
        };
        // the engine's stop arrives without an animation frame, the flags only with one
        const stoppedAfterStart = ({ kind, recording, contextTime }) => kind === "stop" && recording && engine.recordingStart.mapOr(start => contextTime >= start.contextTime, false);
        terminator.ownAll(engine.isRecording.subscribe(stop), engine.isCountingIn.subscribe(stop), engine.subscribeTransportAnchors(anchors => { if (anchors.some(stoppedAfterStart)) {
            finish();
        } }), Terminable.create(() => {
            this.#countIn = false;
            this.#startPosition = 0.0;
        }));
        this.#countIn = countIn && !engine.isPlaying.getValue();
        this.#startPosition = engine.position.getValue();
        return terminator;
    }
    #setRecording(value) {
        if (this.#isRecording === value) {
            return;
        }
        this.#isRecording = value;
        RecordingSession.#active += value ? 1 : -1;
    }
}
