import { Strings, UUID } from "@opendaw/lib-std";
import { WclapInstrumentBox } from "@opendaw/studio-boxes";
import { InstrumentFactories, ProjectQueries } from "@opendaw/studio-adapters";
import { WclapBoxes } from "./WclapBoxes";
