const createCubedStep = (context, field, name) => {
    const read = () => CubedStepCodec.unpack(field.getValue());
    const write = (step) => context.edit(() => field.setValue(CubedStepCodec.pack(step)));
    return Object.freeze({
        get note() { return read().note; },
        set note(value) { write({ ...read(), note: Guard.int32({ min: 0, max: 127 }, value, `${name}.note`) }); },
        get active() { return read().active; },
        set active(value) { write({ ...read(), active: Guard.boolean(value, `${name}.active`) }); },
        get slide() { return read().slide; },
        set slide(value) { write({ ...read(), slide: Guard.boolean(value, `${name}.slide`) }); },
        get accent() { return read().accent; },
        set accent(value) { write({ ...read(), accent: Guard.boolean(value, `${name}.accent`) }); }
    });
};
const createCubedPattern = (context, pattern, index) => {
    const steps = Object.freeze(pattern.steps.fields()
        .map((field, stepIndex) => createCubedStep(context, field, `patterns.${index}.steps.${stepIndex}`)));
    const target = {
        steps,
        setSteps: (values) => context.edit(() => {
            if (!Array.isArray(values)) {
                return panic(new TypeError("setSteps: expected an array"));
            }
            if (values.length > steps.length) {
                return panic(new RangeError(`setSteps: at most ${steps.length} steps`));
            }
            values.forEach((value, stepIndex) => Props.apply(steps[stepIndex], value, `steps.${stepIndex}`));
            pattern.length.setValue(clamp(values.length, 1, steps.length));
        })
    };
    Fields.bind(context, target, { length: pattern.length }, `patterns.${index}.`);
    return target;
};
export class CubedImpl extends InstrumentFacade {
    key = "Cubed";
    patterns;
    constructor(context, box) {
        super(context, box);
        this.bind({
            tuning: box.tuning, cutoff: box.cutoff, resonance: box.resonance, envMod: box.envMod,
            decay: box.decay, accent: box.accent, volume: box.volume, waveform: box.waveform,
            patternIndex: box.patternIndex
        });
        this.patterns = Object.freeze(box.patterns.fields().map((pattern, index) => createCubedPattern(context, pattern, index)));
    }
    get groove() { return GrooveImpls.read(this.context, this.box.groove); }
    set groove(value) { GrooveImpls.write(this.context, this.box.groove, value); }
}
