export var InstrumentImpls;
(function (InstrumentImpls) {
    InstrumentImpls.wrap = (context, box) => context.facade(box, () => {
        if (box instanceof VaporisateurDeviceBox) {
            return new VaporisateurImpl(context, box);
        }
        if (box instanceof PlayfieldDeviceBox) {
            return new PlayfieldImpl(context, box);
        }
        if (box instanceof NanoDeviceBox) {
            return new NanoImpl(context, box);
        }
        if (box instanceof SoundfontDeviceBox) {
            return new SoundfontImpl(context, box);
        }
        if (box instanceof MIDIOutputDeviceBox) {
            return new MIDIOutputImpl(context, box);
        }
        if (box instanceof TapeDeviceBox) {
            return new TapeImpl(context, box);
        }
        if (box instanceof NeonDeviceBox) {
            return new NeonImpl(context, box);
        }
        if (box instanceof TubularDeviceBox) {
            return new TubularImpl(context, box);
        }
        if (box instanceof CubedDeviceBox) {
            return new CubedImpl(context, box);
        }
        if (box instanceof ApparatDeviceBox) {
            return new ApparatImpl(context, box);
        }
        if (box instanceof InstrumentCompositeBox) {
            return new InstrumentCompositeImpl(context, box);
        }
        return panic(`${box.name} is not a supported instrument`);
    });
    InstrumentImpls.isBox = (box) => DeviceBoxes.isInstrumentBox(box.name);
})(InstrumentImpls || (InstrumentImpls = {}));
